p as (select x.id, x.epcad_property_id from parcels x, org where x.org_id = org.id and x.epcad_property_id in (select prop_id from notes)),
del as (delete from liens l using p where l.parcel_id = p.id and l.instrument_number = 'clerk-name-search' returning l.id),
ins as (
  insert into liens (org_id, parcel_id, lien_type, holder, recorded_date, instrument_number)
  select (select id from org), p.id, lz.lien_type, lz.holder, lz.recorded::date, 'clerk-name-search' from lz join p on p.epcad_property_id = lz.prop_id
  returning id
),
upd as (
  update parcels x set notes = concat_ws(E'\n', nullif(regexp_replace(coalesce(x.notes, ''), E'\n?Clerk records \\(owner name search[^\n]*', '', 'g'), ''), n.note), updated_at = now()
  from notes n where x.epcad_property_id = n.prop_id and x.id in (select id from p)
  returning x.id
)
select (select count(*) from p) as properties, (select count(*) from ins) as liens_added, (select count(*) from upd) as notes_updated;
